    lvlsub[0x15].szName = "Expansion";
    lvlsub[0x15].nSize = 0;
    lvlsub[0x15].nOffset = 0x158;
    lvlsub[0x15].fpLinker = 0;
    lvlsub[0x16].szName = "end";
    lvlsub[0x16].eType = FIELDTYPE_END;
    lvlsub[0x16].nSize = 0;
    lvlsub[0x16].nOffset = 0;
    lvlsub[0x16].fpLinker = 0;
